// Package httpx provides net/http server building blocks and middleware for
// genapi services: a TLS/mTLS listener with hardened timeouts and body-size
// limits, transparent gzip response compression (with BREACH-sensitive path
// exclusions), token-bucket rate limiting (a coarse per-IP abuse ceiling plus
// stricter per-path-prefix and per-peer buckets), CORS handling, and the
// default-deny security response-header set (CSP, COOP/COEP/CORP,
// Permissions-Policy). It depends only on the standard library plus the
// internal rate-bucket and obsx observability helpers.
// Code generated by genapi; DO NOT EDIT.
package httpx

import (
	"context"
	"crypto/tls"
	"encoding/json/v2"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/url"
	"strconv"
	"strings"
	"time"

	"geodedb.com/geode-ui/gen/pkg/internal/ratebucket"
	"geodedb.com/geode-ui/gen/pkg/obsx"
	"geodedb.com/geode-ui/gen/pkg/securex/fipsx"
)

// Config holds runtime server settings.
type Config struct {
	Bind           string
	TLSCert        string
	TLSKey         string
	MTLSCA         string
	ReadHeader     time.Duration
	ReadTimeout    time.Duration
	WriteTimeout   time.Duration
	IdleTimeout    time.Duration
	MaxHeaderBytes int
	MaxBodyBytes   int64
	CORSEnabled    bool
	CORSOrigins    []string
	// EnableCompression turns on transparent gzip of text-ish JSON
	// responses (>=1 KiB; client must send Accept-Encoding: gzip).
	EnableCompression bool
	// CompressionExcludePaths lists request paths whose responses must
	// never be gzipped, even when EnableCompression is true. Use for
	// BREACH-sensitive routes (OAuth token endpoints, login, anything
	// emitting bearer tokens or session cookies). Matching is exact with
	// a trailing-slash tolerance (no regex, no wildcards). Empty/nil
	// preserves today's behaviour (compress every eligible response).
	CompressionExcludePaths []string
	// PerIPRPS / PerIPBurst configure a coarse global token bucket
	// partitioned by client IP, applied to every route as an abuse
	// ceiling underneath any tighter per-route limiters. Zero disables.
	PerIPRPS   float64
	PerIPBurst float64
	// PerIPSource selects the key extractor for the per-IP limiter.
	PerIPSource IPSource
	// PathRateLimits install stricter per-IP buckets for matching path
	// prefixes (F3), applied as the outermost layer (before the global per-IP
	// limiter) so e.g. /v1/auth/* gets a tighter credential-stuffing ceiling.
	PathRateLimits []PathLimit

	// Security response headers (SEC-0023). The hardened set —
	// Content-Security-Policy, Cross-Origin-Opener/Embedder/Resource-Policy,
	// and Permissions-Policy — is emitted by default with deny-by-default
	// values suitable for a JSON API. For each field: an empty string emits
	// the secure default; a non-empty string overrides it; the literal "-"
	// suppresses that single header. DisableSecurityHeaders drops the whole
	// hardened set at once (the legacy HSTS/X-Content-Type-Options/
	// X-Frame-Options/Referrer-Policy headers are always emitted regardless).
	ContentSecurityPolicy     string
	CrossOriginOpenerPolicy   string
	CrossOriginEmbedderPolicy string
	CrossOriginResourcePolicy string
	PermissionsPolicy         string
	DisableSecurityHeaders    bool
}

// secHeaderDefaults holds the deny-by-default values for the SEC-0023 hardened
// header set. default-src 'none' plus same-origin isolation is the correct
// posture for a pure-JSON API surface that serves no HTML, scripts, or frames.
var secHeaderDefaults = [...]struct{ name, def string }{
	{"Content-Security-Policy", "default-src 'none'; frame-ancestors 'none'; base-uri 'none'; form-action 'none'"},
	{"Cross-Origin-Opener-Policy", "same-origin"},
	{"Cross-Origin-Embedder-Policy", "require-corp"},
	{"Cross-Origin-Resource-Policy", "same-origin"},
	{"Permissions-Policy", "accelerometer=(), camera=(), geolocation=(), gyroscope=(), magnetometer=(), microphone=(), payment=(), usb=()"},
}

// applySecurityHeaders emits the SEC-0023 hardened header set onto h, honouring
// per-header overrides/suppression and the global disable switch in cfg.
func applySecurityHeaders(h http.Header, cfg Config) {
	if cfg.DisableSecurityHeaders {
		return
	}
	overrides := [...]string{
		cfg.ContentSecurityPolicy,
		cfg.CrossOriginOpenerPolicy,
		cfg.CrossOriginEmbedderPolicy,
		cfg.CrossOriginResourcePolicy,
		cfg.PermissionsPolicy,
	}
	for i, hd := range secHeaderDefaults {
		v := overrides[i]
		switch v {
		case "-": // explicit per-header suppression
			continue
		case "": // unset -> secure default
			h.Set(hd.name, hd.def)
		default: // explicit override
			h.Set(hd.name, v)
		}
	}
}

// tokenBucket aliases the canonical token bucket; httpx previously carried a
// byte-identical private copy (QG-046/059/PERF-0044).
type tokenBucket = ratebucket.Bucket

func newBucket(rate, burst float64) *tokenBucket {
	return ratebucket.New(rate, burst)
}

// ErrInvalidOrigin is returned by ValidateOrigins for a malformed CORS origin.
var ErrInvalidOrigin = errors.New("httpx: invalid CORS origin")

// ValidateOrigins checks a CORS origin allowlist for boot-time safety (used by
// the GENAPI_CORS_ORIGINS runtime override). Each origin must be a non-empty
// absolute URL (scheme://host) with no whitespace/control chars, and must not
// be the wildcard "*" (ValidateConfig forbids "*" when CORS is enabled). An
// empty list is valid.
func ValidateOrigins(origins []string) error {
	for _, o := range origins {
		if o == "" {
			return fmt.Errorf("%w: empty origin", ErrInvalidOrigin)
		}
		if o == "*" {
			return fmt.Errorf("%w: wildcard \"*\" is not allowed", ErrInvalidOrigin)
		}
		for _, r := range o {
			if r <= ' ' || r == 0x7f {
				return fmt.Errorf("%w: %q contains whitespace or control characters", ErrInvalidOrigin, o)
			}
		}
		u, err := url.Parse(o)
		if err != nil || u.Scheme == "" || u.Host == "" {
			return fmt.Errorf("%w: %q is not an absolute scheme://host URL", ErrInvalidOrigin, o)
		}
	}
	return nil
}

// ErrCORSWildcardWithCredentials is returned by ValidateConfig when CORS is
// enabled and any configured origin is the literal "*". Allowing a wildcard
// origin while a server also accepts credentials (cookies, Authorization
// headers, mTLS client certs) is forbidden by the CORS spec
// (https://fetch.spec.whatwg.org/#cors-protocol-and-credentials) and is a
// well-known misconfiguration that nullifies the same-origin protection of
// any session cookie or bearer token the server issues. We refuse the
// configuration at startup so the misconfiguration is discoverable in CI
// instead of silently shipping to production. Disable CORS or list explicit
// origins instead.
var ErrCORSWildcardWithCredentials = errors.New("httpx: CORS wildcard origin \"*\" is forbidden when CORS is enabled; list explicit origins or disable CORS")

// ValidateConfig returns a non-nil error if cfg encodes a CORS configuration
// that would let cross-origin callers from any host read responses while the
// server also presents auth-bearing handlers (the common case in this
// generator's output: JWT, API-key, and mTLS auth all attach credentials to
// requests that CORS can replay). Callers should invoke this before passing
// cfg to WrapHandler or Serve. WrapHandler and Serve both call it internally
// as a hard guard; ValidateConfig is exported so it can also be invoked from
// configuration loaders and tests.
func ValidateConfig(cfg Config) error {
	if !cfg.CORSEnabled {
		return nil
	}
	for _, o := range cfg.CORSOrigins {
		if o == "*" {
			return ErrCORSWildcardWithCredentials
		}
	}
	return nil
}

// WrapHandler wraps h with security headers, CORS, and body size limiting per cfg.
// Use this when managing the http.Server directly instead of calling Serve.
//
// WrapHandler panics if cfg fails ValidateConfig. CORS misconfiguration is a
// startup-only condition; we choose to fail loud at startup so CI catches
// the regression rather than silently shipping a CORS policy that defeats
// the purpose of the rest of the security stack.
func WrapHandler(cfg Config, h http.Handler) http.Handler {
	if err := ValidateConfig(cfg); err != nil {
		panic(err)
	}
	inner := h
	if cfg.EnableCompression {
		inner = GzipWithExcludes(inner, cfg.CompressionExcludePaths)
	}
	hs := headers(inner, cfg)
	bl := limitBody(cfg.MaxBodyBytes, hs)
	outer := bl
	if cfg.PerIPRPS > 0 && cfg.PerIPBurst > 0 {
		pl := NewPeerLimiter(cfg.PerIPRPS, cfg.PerIPBurst, cfg.PerIPSource)
		outer = pl.Middleware(bl)
	}
	if ppl := NewPathPeerLimiter(cfg.PathRateLimits); !ppl.Empty() {
		outer = ppl.Middleware(outer)
	}
	return outer
}

// Serve starts an HTTP server with TLS1.3-only and sane defaults.
func Serve(ctx context.Context, cfg Config, mux *http.ServeMux) error {
	if err := ValidateConfig(cfg); err != nil {
		return err
	}
	// Chain (outermost first): per-path-prefix rate limit -> per-IP rate
	// limit -> body limiter -> headers (incl CORS) -> gzip -> mux, then
	// request-id logging.
	var inner http.Handler = mux
	if cfg.EnableCompression {
		inner = GzipWithExcludes(inner, cfg.CompressionExcludePaths)
	}
	hs := headers(inner, cfg)
	lh := limitBody(cfg.MaxBodyBytes, hs)
	outer := lh
	if cfg.PerIPRPS > 0 && cfg.PerIPBurst > 0 {
		pl := NewPeerLimiter(cfg.PerIPRPS, cfg.PerIPBurst, cfg.PerIPSource)
		go func() { <-ctx.Done(); pl.Close() }()
		outer = pl.Middleware(lh)
	}
	if ppl := NewPathPeerLimiter(cfg.PathRateLimits); !ppl.Empty() {
		outer = ppl.Middleware(outer)
	}
	logged := obsx.Middleware(outer)
	ts := &http.Server{
		Addr:              cfg.Bind,
		Handler:           logged,
		ReadHeaderTimeout: cfg.ReadHeader,
		ReadTimeout:       cfg.ReadTimeout,
		WriteTimeout:      cfg.WriteTimeout,
		IdleTimeout:       cfg.IdleTimeout,
		MaxHeaderBytes:    cfg.MaxHeaderBytes,
	}
	if cfg.TLSCert != "" && cfg.TLSKey != "" {
		ts.TLSConfig = fipsx.NewServerTLSConfig(nil)
		ln, err := (&net.ListenConfig{}).Listen(ctx, "tcp", cfg.Bind)
		if err != nil {
			return err
		}
		tlsLn := tls.NewListener(ln, ts.TLSConfig)
		go func() { <-ctx.Done(); _ = ts.Close() }()
		return ts.ServeTLS(tlsLn, cfg.TLSCert, cfg.TLSKey)
	}
	go func() { <-ctx.Done(); _ = ts.Close() }()
	return ts.ListenAndServe()
}

// DecodeJSON reads JSON from r into v, rejecting unknown fields.
func DecodeJSON(r io.Reader, v any) error {
	return json.UnmarshalRead(r, v, json.RejectUnknownMembers(true))
}

// headers applies HSTS, X-Content-Type-Options, X-Frame-Options, Referrer-Policy,
// the SEC-0023 hardened set (CSP/COOP/COEP/CORP/Permissions-Policy, see
// applySecurityHeaders), and optional CORS.
func headers(next http.Handler, cfg Config) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Strict-Transport-Security", "max-age=63072000; includeSubDomains; preload")
		w.Header().Set("X-Content-Type-Options", "nosniff")
		w.Header().Set("X-Frame-Options", "DENY")
		w.Header().Set("Referrer-Policy", "no-referrer")
		applySecurityHeaders(w.Header(), cfg)
		if cfg.CORSEnabled && len(cfg.CORSOrigins) > 0 {
			orig := r.Header.Get("Origin")
			if orig != "" {
				allowed := false
				for _, o := range cfg.CORSOrigins {
					if o == "*" || strings.EqualFold(o, orig) {
						allowed = true
						break
					}
				}
				if allowed {
					w.Header().Set("Access-Control-Allow-Origin", orig)
					w.Header().Add("Vary", "Origin")
					// Preflight handling (OPTIONS)
					if r.Method == http.MethodOptions {
						w.Header().Set("Access-Control-Allow-Methods", "GET,POST,PUT,DELETE,OPTIONS")
						reqHeaders := r.Header.Get("Access-Control-Request-Headers")
						if reqHeaders == "" {
							reqHeaders = "Content-Type, Authorization"
						}
						w.Header().Set("Access-Control-Allow-Headers", reqHeaders)
						w.WriteHeader(http.StatusNoContent)
						return
					}
				}
			}
		}
		next.ServeHTTP(w, r)
	})
}

func limitBody(max int64, next http.Handler) http.Handler {
	if max <= 0 {
		return next
	}
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.ContentLength > 0 && r.ContentLength > max {
			http.Error(w, ErrBodyTooLarge.Error(), http.StatusRequestEntityTooLarge)
			return
		}
		r.Body = http.MaxBytesReader(w, r.Body, max)
		next.ServeHTTP(w, r)
	})
}

// RouteLimiter applies a token bucket per route and sets X-RateLimit-* headers.
func RouteLimiter(rate, burst float64, next http.Handler) http.Handler {
	b := newBucket(rate, burst)
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		lim, rem, reset := b.Snapshot()
		w.Header().Set("X-RateLimit-Limit", strconv.Itoa(lim))
		w.Header().Set("X-RateLimit-Remaining", strconv.Itoa(rem))
		w.Header().Set("X-RateLimit-Reset", strconv.FormatInt(reset.Unix(), 10))
		if !b.Allow() {
			http.Error(w, ErrRateLimited.Error(), http.StatusTooManyRequests)
			return
		}
		next.ServeHTTP(w, r)
	})
}

// Mux returns a new ServeMux and a helper to mount JSON routes with rate limits.
type Mux struct{ *http.ServeMux }

// NewMux constructs a new mux wrapper.
func NewMux() *Mux { return &Mux{ServeMux: http.NewServeMux()} }

// HandleJSON registers a JSON route with optional rate limiting.
func (m *Mux) HandleJSON(path, method string, h func(http.ResponseWriter, *http.Request), rate, burst float64) {
	hnd := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != method {
			w.WriteHeader(http.StatusMethodNotAllowed)
			return
		}
		h(w, r)
	})
	var final http.Handler = hnd
	if rate > 0 && burst > 0 {
		final = RouteLimiter(rate, burst, final)
	}
	m.Handle(path, final)
}
